from typing import Any
from fastapi import FastAPI
from pydantic import BaseModel, ConfigDict
import uvicorn
from fastapi.testclient import TestClient

class MyCustomClass:
    def __init__(self, name: str):
        self.name = name

class MyModel(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    custom_field: MyCustomClass

app = FastAPI()

@app.post("/test")
async def test_endpoint(model: MyModel):
    return {"name": model.custom_field.name}

client = TestClient(app)

def test_arbitrary_type():
    response = client.post("/test", json={"custom_field": {"name": "test"}})
    # This might fail if FastAPI/Pydantic doesn't know how to parse MyCustomClass from dict
    # or if FastAPI's internal type checking fails.
    print(f"Status code: {response.status_code}")
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"name": "test"}

if __name__ == "__main__":
    try:
        test_arbitrary_type()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed with error: {e}")
        import traceback
        traceback.print_exc()

