import asyncio
import functools
import inspect
from dataclasses import dataclass
from typing import Any

def iscoroutinefunction(obj):
    return inspect.iscoroutinefunction(obj)

def isgeneratorfunction(obj):
    return inspect.isgeneratorfunction(obj)

def isasyncgenfunction(obj):
    return inspect.isasyncgenfunction(obj)

@dataclass
class Dependant:
    call: Any = None

    @property
    def _unwrapped_call(self) -> Any:
        if self.call is None:
            return self.call
        unwrapped = inspect.unwrap(self.call)
        if isinstance(unwrapped, functools.partial):
            unwrapped = unwrapped.func
        return unwrapped

    @property
    def is_gen_callable(self) -> bool:
        if inspect.isgeneratorfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isgeneratorfunction(dunder_call)

    @property
    def is_async_gen_callable(self) -> bool:
        if inspect.isasyncgenfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isasyncgenfunction(dunder_call)

    @property
    def is_coroutine_callable(self) -> bool:
        if inspect.isroutine(self._unwrapped_call):
            return iscoroutinefunction(self._unwrapped_call)
        if inspect.isclass(self._unwrapped_call):
            return False
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return iscoroutinefunction(dunder_call)

def test_repro():
    # Case 1: partial of async function
    async def async_func():
        pass

    p_async = functools.partial(async_func)
    d1 = Dependant(call=p_async)
    print(f"Case 1: is_coroutine_callable={d1.is_coroutine_callable}") # Should be True

