from copy import deepcopy
from typing import Any, Dict

REF_TEMPLATE = "#/components/schemas/{model}"

def _replace_refs(
    *,
    schema: Dict[str, Any],
    old_name_to_new_name_map: Dict[str, str],
) -> Dict[str, Any]:
    new_schema = deepcopy(schema)
    for key, value in new_schema.items():
        if key == "$ref":
            value = schema["$ref"]
            if isinstance(value, str):
                ref_name = schema["$ref"].split("/")[-1]
                if ref_name in old_name_to_new_name_map:
                    new_name = old_name_to_new_name_map[ref_name]
                    new_schema["$ref"] = REF_TEMPLATE.format(model=new_name)
            continue
        if isinstance(value, dict):
            new_schema[key] = _replace_refs(
                schema=value,
                old_name_to_new_name_map=old_name_to_new_name_map,
            )
        elif isinstance(value, list):
            new_value = []
            for item in value:
                if isinstance(item, dict):
                    new_item = _replace_refs(
                        schema=item,
                        old_name_to_new_name_map=old_name_to_new_name_map,
                    )
                    new_value.append(new_item)

                else:
                    new_value.append(item)
            new_schema[key] = new_value
    return new_schema

def test_reproduce():
    schema = {
        "components": {
            "schemas": {
                "OldModel": {
                    "properties": {
                        "field": {"$ref": "#/components/schemas/OldModel"}
                    }
                }
            }
        }
    }
    # Wait, the $ref in the schema is "#/components/schemas/OldModel"
    # The split("/")[-1] will be "OldModel"

    old_name_to_new_name_map = {"OldModel": "NewModel"}

    # Let's try a simpler schema that might trigger it
    schema = {
        "some_key": {
            "$ref": "#/components/schemas/OldModel"
        }
    }

    try:
        result = _replace_refs(schema=schema, old_name_to_new_name_map=old_name_to_new_name_map)
        print("Result:", result)
    except Exception as e:
        print("Caught exception:", type(e).__name__, ":", e)
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_reproduce()

