from typing import List, Union, Optional
from fastapi import FastAPI, Query
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/items/")
async def read_items(q: List[str] | None = Query(None)):
    return {"q": q}

@app.get("/items2/")
async def read_items2(q: Optional[List[str]] = Query(None)):
    return {"q": q}

@app.get("/items3/")
async def read_items3(q: Union[List[str], None] = Query(None)):
    return {"q": q}

client = TestClient(app)

def test_read_items_union_syntax():
    # Test list[str] | None
    response = client.get("/items/?q=foo&q=bar")
    assert response.status_code == 200
    assert response.json() == {"q": ["foo", "bar"]}

    response = client.get("/items/")
    assert response.status_code == 200
    assert response.json() == {"q": None}

def test_read_items2_optional():
    # Test Optional[List[str]]
    response = client.get("/items2/?q=foo&q=bar")
    assert response.status_code == 200
    assert response.json() == {"q": ["foo", "bar"]}

    response = client.get("/items2/")
    assert response.status_code == 200
    assert response.json() == {"q": None}

