from copy import deepcopy
from typing import Any, Dict

REF_TEMPLATE = "#/components/schemas/{model}"

def _replace_refs(
    *,
    schema: Dict[str, Any],
    old_name_to_new_name_map: Dict[str, str],
) -> Dict[str, Any]:
    new_schema = deepcopy(schema)
    for key, value in new_schema.items():
        if key == "\$ref":
            value = schema["\$ref"]
            if isinstance(value, str):
                ref_name = schema["\$ref"].split("/")[-1]
                if ref_name in old_name_to_new_name_map:
                    new_name = old_name_to_new_name_map[ref_name]
                    new_schema["\$ref"] = REF_TEMPLATE.format(model=new_name)
            continue
        if isinstance(value, dict):
            new_schema[key] = _replace_refs(
                schema=value,
                old_name_to_new_name_map=old_name_to_new_name_map,
            )
        elif isinstance(value, list):
            new_value = []
            for item in value:
                if isinstance(item, dict):
                    new_item = _replace_refs(
                        schema=item,
                        old_name_to_new_name_map=old_name_to_new_name_map,
                    )
                    new_value.append(new_item)
                else:
                    new_value.append(item)
            new_schema[key] = new_value
    return new_schema

def test_reproduce():
    schema = {
        "components": {
            "schemas": {
                "Item": {
                    "properties": {
                        "name": {"type": "string"},
                        "owner": {"\$ref": "#/components/schemas/User"}
                    }
                },
                "User": {
                    "properties": {
                        "id": {"type": "integer"}
                    }
                }
            }
        },
        "other": {"\$ref": "#/components/schemas/Something"}
    }
    # This is a bit contrived, but let's see if we can trigger it.
    # The issue might be when schema is not a dict but we try to access it as one.
    # But the loop is over new_schema.items(), so new_schema must be a dict.
    # And new_schema is a deepcopy of schema.

    old_name_to_new_name_map = {"User": "NewUser"}

    # Let's try a case where schema is not a dict but is passed to _replace_refs
    # Wait, the type hint says schema: Dict[str, Any].
    # If it's not a dict, new_schema = deepcopy(schema) might still work if schema is something else.
    # But new_schema.items() will fail if new_schema is not a dict.

    print("Running test...")
    result = _replace_refs(schema=schema, old_name_to_new_name_map=old_name_to_new_name_map)
    print("Result:", result)

if __name__ == "__main__":
    test_reproduce()
