from fastapi import FastAPI, Depends
from fastapi.security import OAuth2PasswordBearer, SecurityScopes
from typing import Annotated

app = FastAPI()

oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token", scopes={"read": "Read data", "write": "Write data"})

def get_current_user(security_scopes: SecurityScopes = Depends()):
    if security_scopes.scopes:
        print(f"Scopes: {security_scopes.scopes}")
    return True

# Scenario 1: Parent dependency with scopes, sub-dependency without scopes
# Actually, the problem says "parent dependency with scopes, sub-dependency security scheme without scopes"
# This might mean:
# path_op -> depends(parent_with_scopes) -> depends(sub_without_scopes)

def sub_dependency():
    return True

def parent_dependency(sub: Annotated[bool, Depends(sub_dependency)], security_scopes: SecurityScopes = Depends(oauth2_scheme)):
    return True

@app.get("/parent")
def read_parent(user: Annotated[bool, Depends(parent_dependency)]):
    return {"message": "parent"}

# Scenario 2: The same security scheme used as another sub-dependency without scopes in a different path operation.
# Path 1: uses oauth2_scheme with scopes
# Path 2: uses oauth2_scheme without scopes (as a sub-dependency)

def sub_dependency_without_scopes(security_scopes: SecurityScopes = Depends(oauth2_scheme)):
    return True

@app.get("/path1")
def read_path1(user: Annotated[bool, Depends(parent_dependency)]):
    return {"message": "path1"}

@app.get("/path2")
def read_path2(sub: Annotated[bool, Depends(sub_dependency_without_scopes)]):
    return {"message": "path2"}

if __name__ == "__main__":
    import json
    openapi_schema = app.openapi()
    print(json.dumps(openapi_schema, indent=2))

