from typing import Any, Annotated, Literal
from pydantic import BaseModel, Field
from pydantic.annotated_handlers import Tag, Discriminator
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int


class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"


class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"


def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))


Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]


app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()


client = TestClient(app)

def test_dessert_apple_pie():
    payload = {
        "time_to_cook": 10,
        "num_ingredients": 3,
        "fruit": "apple"
    }
    response = client.post("/dessert", json=payload)
    assert response.status_code == 200
    assert response.json() == payload

def test_dessert_pumpkin_pie():
    payload = {
        "time_to_cook": 20,
        "num_ingredients": 5,
        "filling": "pumpkin"
    }
    response = client.post("/dessert", json=payload)
    assert response.status_code == 200
    assert response.json() == payload

if __name__ == "__main__":
    test_dessert_apple_pie()
    test_dessert_pumpkin_pie()
    print("Tests passed!")

